/* Science — IXL Canada Grade 6–8 skills (added for IXL alignment).
   B(): question bank [question, answer, wrongs, why]; C(): sort items into categories. */
import { pairs, classify, ri, pick, shuffle } from '../quiz.js';

const sk = (k, t, s, g, gen) => ({ k, t, s, g, gen });
const G = (a, z) => Array.from({ length: z - a + 1 }, (_, i) => a + i);
const B = (k, t, s, g, items) => sk(k, t, s, g, pairs({ items: items.map(([q, a, w, n]) => [q, a, n, [a, ...w]]) }));
const C = (k, t, s, g, categories, items, ask) => sk(k, t, s, g, classify({ categories, items, prompt: x => `${ask}<br>${x}` }));
const num = (prompt, answer, explain) => ({ type: 'num', prompt, answer, explain });
const mcq = (prompt, answer, wrong, explain) => ({ type: 'mc', prompt, answer, choices: shuffle([answer, ...shuffle([...new Set(wrong.map(String))].filter(w => w !== String(answer))).slice(0, 3)]), explain });

/* ---------- speed, distance, time ---------- */
const sdt = kind => () => {
  const v = pick([2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 25]), t = pick([2, 3, 4, 5, 6, 8, 10]), d = v * t;
  const k = kind === 'mix' ? pick(['speed', 'distance', 'time']) : kind;
  if (k === 'speed') return num(`A cyclist travels ${d} m in ${t} s. What is the cyclist's average speed in m/s?`, v, `speed = distance ÷ time = ${d} ÷ ${t} = ${v} m/s.`);
  if (k === 'distance') return num(`A train moves at ${v} m/s for ${t} s. How far does it travel, in metres?`, d, `distance = speed × time = ${v} × ${t} = ${d} m.`);
  return num(`A runner covers ${d} m at a speed of ${v} m/s. How many seconds does it take?`, t, `time = distance ÷ speed = ${d} ÷ ${v} = ${t} s.`);
};

/* ---------- formulas ---------- */
const FORMULAS = [['H₂O', 'water', { H: 2, O: 1 }], ['CO₂', 'carbon dioxide', { C: 1, O: 2 }], ['CH₄', 'methane', { C: 1, H: 4 }], ['NH₃', 'ammonia', { N: 1, H: 3 }], ['O₂', 'oxygen gas', { O: 2 }],
  ['NaCl', 'sodium chloride', { Na: 1, Cl: 1 }], ['C₆H₁₂O₆', 'glucose', { C: 6, H: 12, O: 6 }], ['H₂O₂', 'hydrogen peroxide', { H: 2, O: 2 }], ['N₂', 'nitrogen gas', { N: 2 }], ['CaCO₃', 'calcium carbonate', { Ca: 1, C: 1, O: 3 }]];
const total = c => Object.values(c).reduce((a, b) => a + b, 0);
const describe = c => Object.entries(c).map(([e, n]) => `${n} ${e}`).join(', ');

